function validate([nums, original]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value in nums is between 1 and 1000.';
  if (!Number.isInteger(original) || original < 1 || original > 1000) return 'original is between 1 and 1000.';
  return null;
}

