function generate(rand, size) {
  const n = size === 'large' ? 1000 - Math.floor(rand() * 20) : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 1000 : 1 + Math.floor(rand() * 40);
  const original = 1 + Math.floor(rand() * Math.min(top, size === 'large' ? 60 : 12));
  const nums = [];
  // Plant a chain original, 2*original, 4*original... that may be cut short, so answers vary.
  const skip = rand() < 0.3 ? Math.floor(rand() * 6) : -1;
  for (let value = original, step = 0; value <= 1000 && nums.length < n; value *= 2, step++) {
    if (step !== skip) nums.push(value);
  }
  while (nums.length < n) nums.push(1 + Math.floor(rand() * top));
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums, original];
}
